static int32_t usb_win_show(usb_state_e usb_state);

const usb_flow_t g_usb_flow = {
    usb_win_show,
};

static int32_t usb_win_show(usb_state_e usb_state)
{
    backlight_turn_on();
    if(usb_state == USB_STATE_PLUG_IN) {
        alv_am_app_enter(NULL ,"usb", NULL);
    } else if(usb_state == USB_STATE_PLUG_OUT) {
        if(true == alv_am_app_is_exist("usb")) {
            if(0 != alv_am_win_exit_current(NULL)) {
                alv_am_app_exit(NULL, "usb", NULL);
            }
        }
        comp_msgbox_info_t msgbox_info = {0};
        msgbox_info.timeout = 3000;
        msgbox_info.title = LV_SYMBOL_USB;
        msgbox_info.content = "USB plug out";
        comp_msgbox_create(lv_scr_act(), &msgbox_info);
    } else {
        LV_LOG_ERROR("[%s] usbInfo->state %d is error value", __func__, usb_state);
    }

    return 0;
}

void usb_win_active(lv_obj_t *win, void *p_param)
{
    /* create usb controls */
    ui_usb_init();

    /*no sd card, hidden the panel*/
    if(false == usb_flow_get_sdcard_exist()) {
        lv_obj_add_flag(ui_PnlMsc, LV_OBJ_FLAG_HIDDEN);
    }
    lv_group_add_obj(lv_group_get_default(), ui_PnlChargingOnly);
    lv_group_add_obj(lv_group_get_default(), ui_PnlRndis);
    lv_group_add_obj(lv_group_get_default(), ui_PnlEcm);
    lv_group_add_obj(lv_group_get_default(), ui_PnlMsc);

    lv_group_focus_obj(ui_PnlChargingOnly);
}

void usb_win_deactive(lv_obj_t *win, void *p_param)
{
    lv_obj_del(ui_Usb);
}

void usb_win_focus(lv_obj_t *win, void *p_param)
{
    lv_disp_load_scr(ui_Usb);
    /* show statusbar */
    SHOW_STATUSBAR_MAIN_WIN("Select USB Mode");
    lv_group_focus_obj(ui_PnlChargingOnly);
}
